--

DROP TABLE IF EXISTS `wp_srfm_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wp_srfm_payments` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `form_id` bigint unsigned DEFAULT NULL,
  `block_id` varchar(255) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `status` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `total_amount` decimal(26,8) NOT NULL,
  `refunded_amount` decimal(26,8) NOT NULL,
  `currency` varchar(10) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `entry_id` bigint unsigned NOT NULL,
  `gateway` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `type` varchar(30) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `mode` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `transaction_id` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `customer_id` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `subscription_id` varchar(50) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `subscription_status` varchar(20) COLLATE utf8mb4_unicode_520_ci NOT NULL,
  `parent_subscription_id` bigint unsigned NOT NULL DEFAULT '0',
  `payment_data` longtext COLLATE utf8mb4_unicode_520_ci,
  `extra` longtext COLLATE utf8mb4_unicode_520_ci,
  `log` longtext COLLATE utf8mb4_unicode_520_ci,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
